<p class="lead">Elige un evento y emite una entrada. La disponibilidad se comprueba al confirmar.</p><div class="event-grid"><?php $evs=$eventos; foreach($evs as $ev): $available=max(0,$ev['aforo']-$ev['vendidas']); ?><article class="card event-card"><div class="event-card-top"><span class="category"><?= e($ev['categoria']) ?></span><span class="badge <?= $available?'DISPONIBLE':'ANULADA' ?>"><?= $available?'Disponible':'Agotado' ?></span></div><h2><?= e($ev['nombre']) ?></h2><p class="muted"><?= dateLabel($ev['fecha']) ?></p><p class="description"><?= e($ev['descripcion']) ?></p><div class="event-bottom"><strong><?= money($ev['precio']) ?></strong><span><?= $available ?> / <?= $ev['aforo'] ?> disponibles</span></div><form method="post" class="sale-form" data-confirm="¿Confirmar la venta de un boleto para <?= e($ev['nombre']) ?> por <?= e(money($ev['precio'])) ?>?"><?= csrf() ?><input type="hidden" name="action" value="sell"><input type="hidden" name="sale_nonce" value="<?= e($_SESSION['sale_nonce']) ?>"><input type="hidden" name="evento" value="<?= $ev['id_evento'] ?>"><button class="button full" <?= !$available?'disabled':'' ?>><?= $available?'Vender boleto':'Aforo agotado' ?></button></form></article><?php endforeach; if(!$evs): ?><div class="card empty">No hay eventos activos para vender.</div><?php endif ?></div>
